<script setup>import {ref,onMounted} from 'vue';import {useRouter} from 'vue-router';import {api,errorText} from '../services/api.js';const router=useRouter(),trips=ref([]),name=ref(''),description=ref(''),code=ref(''),dialog=ref(false),joinDialog=ref(false),error=ref(''),busy=ref(false);async function load(){try{trips.value=(await api.get('/trips')).data;}catch(e){error.value=errorText(e);}}async function create(){busy.value=true;error.value='';try{const r=await api.post('/trips',{name:name.value,description:description.value});dialog.value=false;router.push('/trips/'+r.data._id);}catch(e){error.value=errorText(e);}finally{busy.value=false;}}async function join(){busy.value=true;error.value='';try{const r=await api.post('/trips/join',{code:code.value});joinDialog.value=false;router.push('/trips/'+r.data._id);}catch(e){error.value=errorText(e);}finally{busy.value=false;}}onMounted(load);</script><template><v-container class="page py-8"><div class="d-flex flex-wrap align-center ga-3 mb-7"><div><h1 class="text-h4 font-weight-bold">ทริปของฉัน</h1><p class="muted">แชร์ค่าใช้จ่ายกับเพื่อนร่วมทริป</p></div><v-spacer/><v-btn variant="outlined" prepend-icon="mdi-account-plus" @click="joinDialog=true">เข้าร่วมด้วยรหัส</v-btn><v-btn color="primary" prepend-icon="mdi-plus" @click="dialog=true">สร้างทริป</v-btn></div><v-alert v-if="error" type="error" class="mb-4" closable @click:close="error=''">{{error}}</v-alert><v-row><v-col v-for="t in trips" :key="t._id" cols="12" sm="6" md="4"><v-card class="soft-card pa-4" elevation="0" @click="router.push('/trips/'+t._id)" hover><v-icon color="primary" size="32">mdi-map-marker-path</v-icon><h3 class="text-h6 mt-3">{{t.name}}</h3><p class="muted text-body-2">{{t.description||'ทริปแชร์ค่าใช้จ่าย'}}</p><v-divider class="my-3"/><div class="d-flex justify-space-between text-body-2"><span>{{t.members.length}} สมาชิก</span><span class="text-primary">เปิดทริป →</span></div></v-card></v-col></v-row><v-card v-if="!trips.length" class="soft-card text-center pa-12" elevation="0"><v-icon size="55" color="grey">mdi-bag-suitcase-outline</v-icon><p class="mt-3">ยังไม่มีทริป เริ่มสร้างหรือเข้าร่วมทริปได้เลย</p></v-card><v-dialog v-model="dialog" max-width="460"><v-card class="pa-5"><h3 class="text-h6 mb-4">สร้างทริปใหม่</h3><v-form @submit.prevent="create"><v-text-field v-model="name" label="ชื่อทริป" required/><v-textarea v-model="description" label="รายละเอียด (ไม่บังคับ)" rows="2"/><v-btn type="submit" color="primary" block :loading="busy">สร้างทริป</v-btn></v-form></v-card></v-dialog><v-dialog v-model="joinDialog" max-width="420"><v-card class="pa-5"><h3 class="text-h6 mb-4">เข้าร่วมทริป</h3><v-form @submit.prevent="join"><v-text-field v-model="code" label="รหัสเชิญทริป" required/><v-btn type="submit" color="primary" block :loading="busy">เข้าร่วม</v-btn></v-form></v-card></v-dialog></v-container></template>